  },
  AvgVideoCaption_148014_Content_95 = {Text = "だが"},
  AvgVideoCaption_148014_Content_96 = {
    Text = "私の剣はまともな戦いをしてからずいぶん経つ"
  },
  AvgVideoCaption_148014_Content_97 = {
